import java.util.Arrays; public class Problem5_DiceThrowTally { static int[] diceSort(int[] a){int[] c=new int[7];for(int v:a){if(v<1||v>6)throw new IllegalArgumentException("Roll must be 1..6");c[v]++;}System.out.print("Counts: ");for(int v=1;v<=6;v++)System.out.print(v+":"+c[v]+" ");System.out.println();int[]o=new int[a.length];int k=0;for(int v=1;v<=6;v++)for(int n=0;n<c[v];n++)o[k++]=v;return o;} public static void main(String[]x){System.out.println("Sorted: "+Arrays.toString(diceSort(new int[]{4,1,6,4,2,1,4})));}}